// What the site shows: everything except the hidden categories.
export const COMPONENTS = ALL_COMPONENTS.filter((c) => !HIDDEN_CATEGORIES.includes(c.category) && !HIDDEN_COMPONENTS.includes(c.slug)).map((c) => (SECTION_NAMES[c.category] ? { ...c, style: sectionOf(c) } : c))

// Components that take children, so usage shows them as wrappers.
export const WRAPPERS = ['TiltCard', 'DraftingGrid', 'SpringButton', 'MagneticButton']

// A component's files, from the cache ('' for any not loaded yet): call
// loadSources(c) first, or use its result.
export const sourceFor = (c) => c.files.map((f) => ({ file: f, code: SOURCE_CACHE.get(f) ?? '' }))
export const sourcesLoaded = (c) => c.files.every((f) => SOURCE_CACHE.has(f))
export async function loadSources(c) {
  await Promise.all(
    c.files.map(async (f) => {
      if (SOURCE_CACHE.has(f)) return
      const load = loaderFor(f)
      SOURCE_CACHE.set(f, load ? await load() : '')
    }),
  )
  return sourceFor(c)
}

// Preset rows only set other controls, so they have no value of their own.
export const valueControls = (c) => c.controls.filter((k) => k.type !== 'presets')

export const defaultsFor = (c) => Object.fromEntries(valueControls(c).map((k) => [k.name, k.default]))

// JSX usage snippet for the current settings (only props that differ from
// the defaults are written out, like a real call site).
export function usageFor(c, values) {
  const tag = c.files[0].replace('.jsx', '')
  const props = valueControls(c)
    .filter((k) => values[k.name] !== k.default)
    .map((k) => {
      const v = values[k.name]
      if (typeof v === 'boolean') return v ? k.name : `${k.name}={false}`
      if (typeof v === 'number') return `${k.name}={${v}}`
      // an uploaded image is a long data URL: show a file path instead
      if (k.type === 'image') return `${k.name}="/your-logo.png"`
      if (/["\n\\]/.test(v)) return `${k.name}={${JSON.stringify(v)}}`
      return `${k.name}="${v}"`
    })
  const wraps = WRAPPERS.includes(tag)
  const open = props.length ? `<${tag}\n  ${props.join('\n  ')}\n` : `<${tag}`
  const body = wraps ? `${open}${props.length ? '' : ''}>\n  {/* your content */}\n</${tag}>` : `${open}${props.length ? '/>' : ' />'}`
  return `import ${tag} from './${tag}'\n\n${body}`
}
